import urllib.request
import json
import time

def fetch_data(station_ids):
    base_url = "https://waterservices.usgs.gov/nwis/dv/?format=json&sites={}&startDT=2025-04-01&endDT=2025-04-07&parameterCd=00060"
    ids_str = ",".join(station_ids)
    url = base_url.format(ids_str)
    try:
        with urllib.request.urlopen(url) as response:
            return json.loads(response.read().decode())
    except Exception as e:
        print(f"Error fetching data: {e}")
        return None

def main():
    with open("/root/data/michigan_stations.txt", "r") as f:
        station_ids = [line.strip() for line in f if line.strip()]

    # Fetch in chunks of 20 to avoid long URLs
    chunk_size = 20
    all_data = []
    for i in range(0, len(station_ids), chunk_size):
        chunk = station_ids[i:i+chunk_size]
        print(f"Fetching chunk {i//chunk_size + 1}...")
        data = fetch_data(chunk)
        if data:
            all_data.append(data)
        time.sleep(1) # Be nice to the API

    results = {}
    for data in all_data:
        if 'timeSeries' not in data['value']:
            continue
        for ts in data['value']['timeSeries']:
            station_id = ts['sourceInfo']['siteCode'][0]['value']
            values = ts['values'][0]['value']
            results[station_id] = values

    with open("/tmp/streamflow_data.json", "w") as f:
        json.dump(results, f)
    print(f"Saved data for {len(results)} stations.")

if __name__ == "__main__":
    main()

